import crypto from 'crypto';
import express, { Request, Response, NextFunction } from 'express';
import session from 'express-session';

interface AgentSession {
  sessionId: string;
  agentId: string;
  serviceToken: string;
  authenticated: boolean;
  createdAt: number;
  lastRotation: number;
}

const SESSION_STORE = new Map<string, AgentSession>();
const ROTATION_INTERVAL_MS = 300000; // 5 minutes
const HMAC_SECRET = crypto.randomBytes(32).toString('hex');

function generateSessionId(): string {
  return crypto.randomBytes(24).toString('base64url');
}

function computeSessionMAC(sessionId: string, agentId: string): string {
  return crypto.createHmac('sha256', HMAC_SECRET)
    .update(`${sessionId}:${agentId}`)
    .digest('hex');
}

function shouldRotateSession(session: AgentSession): boolean {
  return (Date.now() - session.lastRotation) > ROTATION_INTERVAL_MS;
}

function rotateSession(oldSession: AgentSession): AgentSession {
  const newSessionId = generateSessionId();
  const newSession: AgentSession = {
    sessionId: newSessionId,
    agentId: oldSession.agentId,
    serviceToken: oldSession.serviceToken,
    authenticated: oldSession.authenticated,
    createdAt: oldSession.createdAt,
    lastRotation: Date.now()
  };
  SESSION_STORE.delete(oldSession.sessionId);
  SESSION_STORE.set(newSessionId, newSession);
  return newSession;
}

function validateServiceToken(token: string, agentId: string): boolean {
  // Cross-service token validation via shared secret
  const expectedPrefix = crypto.createHash('sha256')
    .update(`agent:${agentId}:${HMAC_SECRET}`)
    .digest('hex')
    .substring(0, 16);
  return token.startsWith(expectedPrefix);
}

const app = express();
app.use(express.json());

// Pre-authentication: agent requests a session before authenticating
app.post('/agent/init', (req: Request, res: Response) => {
  const { agentId } = req.body;
  if (!agentId || typeof agentId !== 'string' || agentId.length > 64) {
    return res.status(400).json({ error: 'Invalid agentId' });
  }

  const sessionId = generateSessionId();
  const agentSession: AgentSession = {
    sessionId,
    agentId,
    serviceToken: '',
    authenticated: false,
    createdAt: Date.now(),
    lastRotation: Date.now()
  };
  SESSION_STORE.set(sessionId, agentSession);

  const mac = computeSessionMAC(sessionId, agentId);
  res.json({ sessionId, mac });
});

// Authentication: agent provides cross-service token
app.post('/agent/authenticate', (req: Request, res: Response) => {
  const { sessionId, mac, serviceToken } = req.body;
  if (!sessionId || !mac || !serviceToken) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  const agentSession = SESSION_STORE.get(sessionId);
  if (!agentSession) {
    return res.status(401).json({ error: 'Unknown session' });
  }

  // Verify MAC to ensure session integrity
  const expectedMAC = computeSessionMAC(sessionId, agentSession.agentId);
  if (!crypto.timingSafeEqual(Buffer.from(mac), Buffer.from(expectedMAC))) {
    return res.status(401).json({ error: 'Invalid MAC' });
  }

  if (!validateServiceToken(serviceToken, agentSession.agentId)) {
    return res.status(401).json({ error: 'Invalid service token' });
  }

  // Authenticate the session - NOTE: session ID is NOT regenerated here
  agentSession.serviceToken = serviceToken;
  agentSession.authenticated = true;
  SESSION_STORE.set(sessionId, agentSession);

  res.json({ status: 'authenticated', sessionId });
});

// Protected endpoint: submit logs
app.post('/agent/logs', (req: Request, res: Response) => {
  const sessionId = req.headers['x-session-id'] as string;
  const mac = req.headers['x-session-mac'] as string;

  if (!sessionId || !mac) {
    return res.status(401).json({ error: 'Missing session headers' });
  }

  let agentSession = SESSION_STORE.get(sessionId);
  if (!agentSession || !agentSession.authenticated) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  const expectedMAC = computeSessionMAC(agentSession.sessionId, agentSession.agentId);
  if (!crypto.timingSafeEqual(Buffer.from(mac), Buffer.from(expectedMAC))) {
    return res.status(401).json({ error: 'Invalid MAC' });
  }

  // Rotate session if needed
  if (shouldRotateSession(agentSession)) {
    agentSession = rotateSession(agentSession);
  }

  // Process logs
  const { logs } = req.body;
  console.log(`[${agentSession.agentId}] Received ${logs?.length || 0} log entries`);

  const newMAC = computeSessionMAC(agentSession.sessionId, agentSession.agentId);
  res.json({ status: 'accepted', sessionId: agentSession.sessionId, mac: newMAC });
});

// Session transfer: allows migrating session to another monitoring node
app.post('/agent/transfer', (req: Request, res: Response) => {
  const { sessionId, mac, targetNodeId } = req.body;
  if (!sessionId || !mac || !targetNodeId) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  const agentSession = SESSION_STORE.get(sessionId);
  if (!agentSession || !agentSession.authenticated) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  const expectedMAC = computeSessionMAC(sessionId, agentSession.agentId);
  if (!crypto.timingSafeEqual(Buffer.from(mac), Buffer.from(expectedMAC))) {
    return res.status(401).json({ error: 'Invalid MAC' });
  }

  // Transfer preserves the session ID for continuity across nodes
  const transferToken = crypto.createHmac('sha256', HMAC_SECRET)
    .update(`transfer:${sessionId}:${targetNodeId}:${Date.now()}`)
    .digest('hex');

  res.json({ transferToken, sessionId: agentSession.sessionId });
});

export default app;
